/**
 * ContractFile.jsx — Page that shows one contract as a PDF (manager, employer or student).
 *
 * Location: components/contracts/ContractFile.jsx
 * Routes: /manager/contracts/:id, /employer/contracts/:id and /student/contracts/:id
 *         (opened by the "Download the contract" button of ContractCard)
 *
 * The PDF is generated by the backend on demand, so it always reflects the current signatures.
 * - FR / EN switch: changes the language of the PDF shown (independent of the language of the
 *   interface; it starts in the interface language).
 * - "Download this PDF": saves the language currently shown.
 * - "Download both": saves the French and the English PDFs one after the other.
 *
 * Opening this page closes the "contract to sign" notification of this contract
 * (and only this one: session-scoped, see NotificationsProvider).
 *
 * Downloaded file name: {language}-{docType}-{studentName}.{extension}
 *   e.g. fr-contract-Alex_Tremblay.pdf
 * The student name comes from the link state set by ContractCard ({studentName}).
 * When the page is opened directly (no link state) the student name is skipped.
 *
 * Access control is handled by <RequireRole/> in App.jsx, and enforced again by the backend
 * (a contract of another party is not found).
 */

import {useMemo} from "react";
import {useOutletContext, useParams} from "react-router-dom";
import {getContractFile} from "../core/api/Api.jsx";
import {TARGET_TYPE, useCloseShownNotifications} from "../notification/NotificationsProvider.jsx";
import {getContractRole} from "../../utils/ContractRole.js";
import PdfFilePage from "../documents/PdfFilePage.jsx";

const ContractFile = () => {
    const {dark, user} = useOutletContext();
    const {id} = useParams();
    const {basePath} = getContractRole(user);
    const contractId = Number(id);
    const shownIds = useMemo(() => [contractId], [contractId]);
    useCloseShownNotifications(TARGET_TYPE.CONTRACT, shownIds);
    return (
        <PdfFilePage
            dark={dark} id={contractId} backTo={basePath}
            titleKey="managerContracts.file.title" subtitleKey="managerContracts.file.subtitle"
            backKey="managerContracts.file.back" docType="contract"
            fetchFile={getContractFile}
        />
    );
};

export default ContractFile;